#if UNITY_EDITOR
using System.Collections.Generic;
using UnityEditor;
using UnityEngine;
using VfxKit;
using static VfxKit.VfxBuildKit;

namespace VfxEffects
{
    // Generated by vfx-shader. The prefab is rebuilt from this script: edit here, not in the Inspector.
    // Plan: Docs/VFX/FireTornado/Plan.md
    // Fire tornado: standing column of fire ~4.5 m, one-shot ~4.4 s (slow rise 0.8 s, hold, collapse + ember burst).
    // Built with the tornado process of the vfx-shader skill (references/tornado.md) but a different tornado from WindTornado:
    //   mesh    : one continuous funnel (tornado_mesh + Thrust shader) instead of loose rings;
    //   layout  : taller column, flame whips stand upright and climb the funnel (ring axis vertical) instead of a flat swirl at the foot;
    //   timing  : slow rise, hold, collapse with an ember burst;
    //   extra   : embers, heat smoke, scorched ground glow, foot flames.
    public static class FireTornadoBuild
    {
        const string Root = "Assets/VFX/FireTornado";
        const string Ref = "Assets/VFX/_Imported/RpgTornado/";
        const string MeshFunnel = Ref + "RPG_VFX/Mesh/tornado_mesh.fbx";                            // hourglass funnel 2 x 2 x 2.42 m (rpg-game)
        const string MeshRing = Ref + "_Game/Resources_moved/Models/fbx_fx_cylinder_03.FBX";        // open ring r 0.59 m, h 0.27 m
        const string SheetElements = Ref + "_Game/Resources_moved/Textures/Tex_fx_elements_set_01.tga";   // channel-packed sheet (cell 6 = flame comet, 14-15 = flame blobs)
        const string Lib = "Assets/Library/";
        const string WindTex = Lib + "noise/noise_098.png";       // streaks scrolled by the Thrust shader
        const string SoftDisc = Lib + "glow/glow_005.png";
        const string ShThrust = "Custom/RPG/ThrustEffect_FinalSoft_CustomData_UV2_LengthFade_Instanced";
        const string ShGraph = "Shader Graphs/Fx_dissolve_particle_apb";

        const float Total = 4.4f;      // life of the funnel (s)
        const float Emit = 3.6f;       // emission window of the other layers
        const float K = 0.62f;         // funnel: mesh 2.42 m x size Z 3 x K = 4.5 m tall

        static readonly Color Core = new Color32(0xFF, 0xD9, 0x7A, 0xFF);   // yellow
        static readonly Color Mid = new Color32(0xFF, 0x7A, 0x1A, 0xFF);    // orange
        static readonly Color Red = new Color32(0xE0, 0x30, 0x08, 0xFF);

        [MenuItem("VFX/FireTornado/Build")]
        public static void Build()
        {
            if (!ConfirmSceneSwitch()) return;
            EnsureFolders(Root, "Materials", "Prefabs", "Scenes");

            var funnel = LoadMesh(MeshFunnel);
            var ring = LoadMesh(MeshRing);
            var wind = Tex(WindTex);
            var disc = Tex(SoftDisc);
            var sheet = Tex(SheetElements);
            var smoke = Tex("Assets/VFX/fx_t_smoke_02.png");   // default smoke

            string M(string n) => Root + "/Materials/M_FireTornado_" + n + ".mat";
            var mBody = Thrust(M("Body"), wind);
            var mWhip = Graph(M("Whips"), sheet, 3025);
            var mFoot = Graph(M("FootFire"), sheet, 3025);
            var mEmber = Graph(M("Embers"), sheet, 3025);
            var mSmoke = Material(M("HeatSmoke"), VfxBlend.Alpha, smoke);
            var mGround = Material(M("Scorch"), VfxBlend.Additive, disc);

            // ---- L1 Funnel (prefab root): one hourglass mesh, flames streak up its skin, spins 1.3 rev/s
            var root = new GameObject("VFX_FireTornado");
            var body = ParticleOn(root, mBody, Total, 1f, Color.white);
            {
                var main = body.main;
                main.startSize3D = true; main.startSizeX = 2.2f * K; main.startSizeY = 2.2f * K; main.startSizeZ = 3f * K;
                main.startRotation3D = true; main.startRotationX = -Mathf.PI / 2f; main.startRotationY = Mathf.PI / 2f; main.startRotationZ = 0f;
                var rot = body.rotationOverLifetime; rot.enabled = true; rot.separateAxes = false; rot.z = 2f * Mathf.PI * 1.3f;
                SizeOverLifetime(body, 0f, 0.12f, 0.18f, 1f, 0.78f, 1f, 0.99f, 0.89f);                      // slow rise 0.8 s, then only a slight sag (art lead fix); alpha fades it out
                ColorOverLifetime(body, new[] { Core, Mid }, 0f, 0f, 0.12f, 1f, 0.8f, 1f, 1f, 0f);
                var r = SetMesh(body, funnel, 3, pivotZ: -0.5f, streams: true);
                Custom1(body);
            }

            // ---- L2 Whips: upright flame bands (ring axis vertical) climbing the funnel while they spin around it
            var whips = Particle(root.transform, "L2_Whips", mWhip, Emit, 1f, Mid);
            {
                var main = whips.main; main.maxParticles = 30;
                main.startLifetime = new ParticleSystem.MinMaxCurve(0.9f, 1.2f);
                main.startSpeed = new ParticleSystem.MinMaxCurve(2.4f * K, 3.4f * K);
                main.startSize3D = true; main.startSizeX = 2f; main.startSizeY = 2f; main.startSizeZ = 3f;   // art lead fix: taller bands
                // MESH AXIS: fbx_fx_cylinder_03 has its ring axis on mesh Z (bounds 0.70 x 1.17 x 0.27, normals in XY: see Describe()). To make the ring
                // hoop round a VERTICAL column (axis up) it needs Start Rotation X = 90 deg; X ~ 0 would lay the axis along the view (art lead fix 2026-11-06).
                main.startRotation3D = true;
                main.startRotationX = Mathf.PI / 2f;
                main.startRotationY = new ParticleSystem.MinMaxCurve(0f, 2f * Mathf.PI);
                main.startRotationZ = 0f;
                main.startColor = new ParticleSystem.MinMaxGradient(Mid, Core);
                Rate(whips, 18f, rise: 0.8f, fall: 0.8f);
                var shape = whips.shape; shape.enabled = true; shape.shapeType = ParticleSystemShapeType.Cone; shape.radius = 0.1f; shape.angle = 0f; shape.rotation = new Vector3(-90f, 0f, 0f);
                var rotl = whips.rotationOverLifetime; rotl.enabled = true; rotl.separateAxes = true;      // all axes the same curve mode
                rotl.x = new ParticleSystem.MinMaxCurve(1f, AnimCurve(0f, 0f, 1f, 0f), AnimCurve(0f, 0f, 1f, 0f));
                rotl.z = new ParticleSystem.MinMaxCurve(1f, AnimCurve(0f, 0f, 1f, 0f), AnimCurve(0f, 0f, 1f, 0f));
                rotl.y = new ParticleSystem.MinMaxCurve(2f * Mathf.PI, AnimCurve(0f, 1.2f, 1f, 0.5f), AnimCurve(0f, 0.7f, 1f, 0.3f));   // 1.1 .. 0.5 rev/s around its own (vertical) axis
                SizeOverLifetime(whips, 0f, 0.55f, 0.3f, 1f, 1f, 1.35f);                                     // widens as it climbs: follows the funnel
                AlphaOverLifetime(whips, 0f, 0f, 0.12f, 1f, 0.7f, 1f, 1f, 0f);
                Tsa(whips, 4, 4, 0.375f, 0.375f);                                                            // cell 6: flame comet
                SetMesh(whips, ring, 5, pivotZ: 0f, streams: true);
                GraphData(whips, new ParticleSystem.MinMaxCurve(1f, AnimCurve(0f, 0.05f, 1f, 1f)), new ParticleSystem.MinMaxCurve(14f), new ParticleSystem.MinMaxCurve(0.03f), 50f, Core);
            }

            // ---- L3 FootFire: flame blobs licking up at the foot (cells 14-15)
            var foot = Particle(root.transform, "L3_FootFire", mFoot, Emit, 1f, Mid);
            {
                var main = foot.main; main.maxParticles = 40;
                main.startLifetime = new ParticleSystem.MinMaxCurve(0.6f, 0.9f);
                main.startSpeed = new ParticleSystem.MinMaxCurve(1.2f, 2.4f);
                main.startSize = new ParticleSystem.MinMaxCurve(0.7f, 1.1f);
                main.startRotation = new ParticleSystem.MinMaxCurve(0f, 2f * Mathf.PI);
                main.startColor = new ParticleSystem.MinMaxGradient(Red, Mid);
                Rate(foot, 9f, rise: 0.8f, fall: 0.8f);
                var shape = foot.shape; shape.enabled = true; shape.shapeType = ParticleSystemShapeType.Circle; shape.radius = 0.85f; shape.radiusThickness = 0.5f; shape.rotation = new Vector3(-90f, 0f, 0f);
                SizeOverLifetime(foot, 0f, 0.7f, 0.3f, 1f, 1f, 0.5f);
                AlphaOverLifetime(foot, 0f, 0f, 0.1f, 1f, 0.7f, 1f, 1f, 0f);
                Tsa(foot, 4, 4, 0.875f, 1f);                                                                 // cells 14-15
                SetBillboard(foot, 6);
                GraphData(foot, new ParticleSystem.MinMaxCurve(1f, AnimCurve(0f, 0f, 1f, 1f)), new ParticleSystem.MinMaxCurve(10f), new ParticleSystem.MinMaxCurve(0.05f), 3f, Core);
            }

            // ---- L4 Embers: sparks spiralling up, then an ember burst when the column collapses
            var embers = Particle(root.transform, "L4_Embers", mEmber, Emit, 1f, Core);
            {
                var main = embers.main; main.maxParticles = 140;
                main.startLifetime = new ParticleSystem.MinMaxCurve(0.8f, 1.4f);
                main.startSpeed = new ParticleSystem.MinMaxCurve(0.6f, 6f);
                main.startSize = new ParticleSystem.MinMaxCurve(0.16f, 0.3f);
                main.startRotation = new ParticleSystem.MinMaxCurve(0f, 2f * Mathf.PI);
                main.startColor = new ParticleSystem.MinMaxGradient((Color)new Color32(0xFF, 0xA0, 0x30, 0xFF), (Color)new Color32(0xFF, 0xE0, 0x80, 0xFF));
                main.gravityModifier = -0.2f;
                var em = embers.emission; em.rateOverTime = new ParticleSystem.MinMaxCurve(34f, AnimCurve(0f, 0.2f, 0.25f, 1f, 0.8f, 1f, 1f, 0.3f));
                em.SetBursts(new[] { new ParticleSystem.Burst(3.3f, 45) });                                  // collapse burst
                var shape = embers.shape; shape.enabled = true; shape.shapeType = ParticleSystemShapeType.Cone; shape.radius = 0.9f; shape.radiusThickness = 0.6f; shape.angle = 30f; shape.rotation = new Vector3(-90f, 0f, 0f);
                var v = embers.velocityOverLifetime; v.enabled = true; v.space = ParticleSystemSimulationSpace.Local;
                var zero = new ParticleSystem.MinMaxCurve(1f, AnimCurve(0f, 0f, 1f, 0f));
                v.x = zero; v.y = zero; v.z = zero; v.radial = zero; v.speedModifier = new ParticleSystem.MinMaxCurve(1f, AnimCurve(0f, 1f, 1f, 1f));
                v.orbitalX = zero; v.orbitalY = new ParticleSystem.MinMaxCurve(5f, AnimCurve(0f, 1f, 1f, 0.3f)); v.orbitalZ = zero;     // swirl round the axis
                SizeOverLifetime(embers, 0f, 0f, 0.1f, 1f, 0.5f, 0.7f, 1f, 0f);
                Tsa(embers, 8, 8, 0.297f, 0.297f);
                SetBillboard(embers, 8);
                GraphData(embers, new ParticleSystem.MinMaxCurve(0f), new ParticleSystem.MinMaxCurve(0f), new ParticleSystem.MinMaxCurve(0.1f, AnimCurve(0f, 0f, 1f, -1f)), 3f, (Color)new Color32(0xFF, 0xB0, 0x30, 0xFF));
            }

            // ---- L5 HeatSmoke: dark smoke rolling off the top (default smoke texture, tinted by Start Color)
            var heat = Particle(root.transform, "L5_HeatSmoke", mSmoke, Emit, 1f, Color.white);
            {
                var main = heat.main; main.maxParticles = 40;
                main.startLifetime = new ParticleSystem.MinMaxCurve(1.6f, 2.2f);
                main.startSpeed = new ParticleSystem.MinMaxCurve(0.8f, 1.5f);
                main.startSize = new ParticleSystem.MinMaxCurve(1.2f, 1.9f);
                main.startRotation = new ParticleSystem.MinMaxCurve(0f, 2f * Mathf.PI);
                main.startColor = new ParticleSystem.MinMaxGradient(new Color(0.23f, 0.16f, 0.13f, 0.34f), new Color(0.32f, 0.22f, 0.17f, 0.22f));
                Rate(heat, 8f, rise: 0.8f, fall: 0.8f);
                var shape = heat.shape; shape.enabled = true; shape.shapeType = ParticleSystemShapeType.Circle; shape.radius = 1.1f; shape.radiusThickness = 0.5f;
                shape.position = new Vector3(0f, 3.8f, 0f); shape.rotation = new Vector3(-90f, 0f, 0f);
                var v = heat.velocityOverLifetime; v.enabled = true; v.space = ParticleSystemSimulationSpace.Local;
                ParticleSystem.MinMaxCurve Two(float a, float b) => new ParticleSystem.MinMaxCurve(a, b);
                v.x = Two(0, 0); v.y = Two(0.4f, 0.8f); v.z = Two(0, 0); v.orbitalX = Two(0, 0); v.orbitalY = Two(1.2f, 2f); v.orbitalZ = Two(0, 0); v.radial = Two(0.3f, 0.6f);
                v.speedModifier = new ParticleSystem.MinMaxCurve(1f, 1f);
                SizeOverLifetime(heat, 0f, 0.5f, 1f, 1.6f);
                AlphaOverLifetime(heat, 0f, 0f, 0.2f, 1f, 0.6f, 0.7f, 1f, 0f);
                var rl = heat.rotationOverLifetime; rl.enabled = true; rl.separateAxes = false; rl.z = Two(-0.6f, 0.6f);
                heat.GetComponent<ParticleSystemRenderer>().sortingOrder = 2;
            }

            // ---- L6 Scorch: orange glow burning the ground under the column (Billboard + Local, laid flat)
            var scorch = Particle(root.transform, "L6_Scorch", mGround, Total, 1f, Color.white);
            {
                scorch.transform.localRotation = Quaternion.Euler(90f, 0f, 0f);
                var main = scorch.main; main.startSize = 3.4f; main.startColor = new Color(1f, 0.42f, 0.1f, 0.6f);
                AlphaOverLifetime(scorch, 0f, 0f, 0.15f, 1f, 0.75f, 0.9f, 1f, 0f);
                SizeOverLifetime(scorch, 0f, 0.6f, 0.2f, 1f, 1f, 1f);
                var r = scorch.GetComponent<ParticleSystemRenderer>(); r.alignment = ParticleSystemRenderSpace.Local; r.sortingOrder = 1;
            }

            var prefab = SavePrefab(root, Root + "/Prefabs/VFX_FireTornado.prefab");
            float d = 8.5f, el = 40f * Mathf.Deg2Rad;
            var cam = new Vector3(0f, 1.8f + d * Mathf.Sin(el), -d * Mathf.Cos(el));    // 3/4 view, 40 deg down (project default)
            Finish(prefab, Root, "FireTornado", new[] { 0.3f, 0.8f, 1.6f, 2.6f, 3.4f, 4.0f }, cam, new Vector3(0f, 1.8f, 0f));
        }

        public static void BuildBatch() => RunBatch(Build);

        // Thrust (rpg-game) on a warm palette: colours inner yellow -> outer orange, two noise layers for turbulence, slight vertex wobble.
        static Material Thrust(string path, Texture2D windTex)
        {
            var m = Material(path, VfxBlend.Alpha, null, ShThrust);
            m.SetFloat("_SrcBlend", 3f); m.SetFloat("_DstBlend", 10f);
            m.SetFloat("_CullMode", 0f);
            m.SetFloat("_FadeBothEnds", 1f); m.EnableKeyword("_FADEBOTHENDS_ON");
            m.SetTexture("_NoiseTex", windTex);
            m.SetColor("_ColorInner", new Color(1f, 0.85f, 0.45f, 1f)); m.SetColor("_ColorOuter", new Color(1f, 0.30f, 0.06f, 1f)); m.SetColor("_EdgeColor", new Color(1f, 0.55f, 0.15f, 1f));
            m.SetVector("_NoiseScroll1", new Vector4(3.5f, -3.2f, 0f, 0f)); m.SetVector("_NoiseScroll2", new Vector4(-2f, -2.4f, 0f, 0f));
            m.SetVector("_NoiseTiling1", new Vector4(2f, 5f, 0f, 0f)); m.SetVector("_NoiseTiling2", new Vector4(3f, 4f, 0f, 0f));
            m.SetFloat("_NoiseStrength", 2.2f);
            m.SetFloat("_Opacity", 1.1f); m.SetFloat("_LengthFade", 0.1f); m.SetFloat("_CustomLengthMultiplier", 1f);
            m.SetFloat("_TipFade", 6f); m.SetFloat("_MainMaskPower", 0.1f);
            m.SetFloat("_ViewEdgeFade", 0f); m.SetFloat("_FresnelPower", 0.1f); m.SetFloat("_FresnelColorStrength", 1.4f);
            m.SetFloat("_VertexWobble", 0.04f); m.SetFloat("_VertexSpeed", 4f); m.SetFloat("_VertexFrequency", 5f);
            m.SetFloat("_Dissolve", 1f); m.SetFloat("_CustomDissolveMultiplier", 0f); m.SetFloat("_DissolveSoftness", 0.001f);
            m.SetFloat("_EdgeIntensity", 5f); m.SetVector("_DissolveScroll", Vector4.zero);
            m.SetFloat("_DirectionalDissolve", 1f); m.SetFloat("_DissolveDirection", 1f); m.SetFloat("_InvertY", 1f);
            EditorUtility.SetDirty(m);
            return m;
        }

        // Reference Shader Graph (Built-in target), property names as in the reference materials.
        static Material Graph(string path, Texture2D sheet, int queue)
        {
            var m = Material(path, VfxBlend.Alpha, null, ShGraph);
            m.SetTexture("Main_tex", sheet); m.SetTextureScale("Main_tex", Vector2.one); m.SetTextureOffset("Main_tex", Vector2.zero);
            m.SetFloat("Vector1_930B327D", -10f); m.SetFloat("Vector1_270105AC", -2f);
            m.SetFloat("Boolean_9C0948F4", 0f); m.SetFloat("Vector1_2C5A3101", 1f);
            m.renderQueue = queue;
            EditorUtility.SetDirty(m);
            return m;
        }

        // Mesh renderer. streams = true: Thrust / Graph stream layout (Position, Normal, Color, UV, [UV2], Custom1, [Custom2]).
        static ParticleSystemRenderer SetMesh(ParticleSystem ps, Mesh mesh, int order, float pivotZ, bool streams)
        {
            var r = ps.GetComponent<ParticleSystemRenderer>();
            r.renderMode = ParticleSystemRenderMode.Mesh; r.mesh = mesh; r.alignment = ParticleSystemRenderSpace.Local;
            r.sortingOrder = order; r.pivot = new Vector3(0f, 0f, pivotZ); r.enableGPUInstancing = false;
            bool graph = r.sharedMaterial != null && r.sharedMaterial.shader.name == ShGraph;
            if (streams)
                r.SetActiveVertexStreams(graph
                    ? new List<ParticleSystemVertexStream> { ParticleSystemVertexStream.Position, ParticleSystemVertexStream.Normal, ParticleSystemVertexStream.Color, ParticleSystemVertexStream.UV, ParticleSystemVertexStream.UV2, ParticleSystemVertexStream.Custom1XYZW, ParticleSystemVertexStream.Custom2XYZW }
                    : new List<ParticleSystemVertexStream> { ParticleSystemVertexStream.Position, ParticleSystemVertexStream.Normal, ParticleSystemVertexStream.Color, ParticleSystemVertexStream.UV, ParticleSystemVertexStream.Custom1XYZW });
            return r;
        }

        static void SetBillboard(ParticleSystem ps, int order)
        {
            var r = ps.GetComponent<ParticleSystemRenderer>();
            r.renderMode = ParticleSystemRenderMode.Billboard; r.alignment = ParticleSystemRenderSpace.View; r.sortingOrder = order; r.enableGPUInstancing = false;
            r.SetActiveVertexStreams(new List<ParticleSystemVertexStream>
            {
                ParticleSystemVertexStream.Position, ParticleSystemVertexStream.Normal, ParticleSystemVertexStream.Color, ParticleSystemVertexStream.UV,
                ParticleSystemVertexStream.UV2, ParticleSystemVertexStream.Custom1XYZW, ParticleSystemVertexStream.Custom2XYZW
            });
        }

        // Thrust reads Custom1 = (extra dissolve [unused, multiplier 0], extra length-fade exponent 1)
        static void Custom1(ParticleSystem ps)
        {
            var cd = ps.customData; cd.enabled = true;
            cd.SetMode(ParticleSystemCustomData.Custom1, ParticleSystemCustomDataMode.Vector);
            cd.SetVectorComponentCount(ParticleSystemCustomData.Custom1, 4);
            cd.SetVector(ParticleSystemCustomData.Custom1, 0, new ParticleSystem.MinMaxCurve(0f));
            cd.SetVector(ParticleSystemCustomData.Custom1, 1, new ParticleSystem.MinMaxCurve(1f));
            cd.SetVector(ParticleSystemCustomData.Custom1, 2, new ParticleSystem.MinMaxCurve(0f));
            cd.SetVector(ParticleSystemCustomData.Custom1, 3, new ParticleSystem.MinMaxCurve(0f));
        }

        // Graph shader: Custom1 = (dissolve, edge sharpness, UV wobble, unused), Custom2 = highlight colour
        static void GraphData(ParticleSystem ps, ParticleSystem.MinMaxCurve dissolve, ParticleSystem.MinMaxCurve sharp, ParticleSystem.MinMaxCurve wobble, float w, Color highlight)
        {
            var cd = ps.customData; cd.enabled = true;
            cd.SetMode(ParticleSystemCustomData.Custom1, ParticleSystemCustomDataMode.Vector);
            cd.SetVectorComponentCount(ParticleSystemCustomData.Custom1, 4);
            cd.SetVector(ParticleSystemCustomData.Custom1, 0, dissolve);
            cd.SetVector(ParticleSystemCustomData.Custom1, 1, sharp);
            cd.SetVector(ParticleSystemCustomData.Custom1, 2, wobble);
            cd.SetVector(ParticleSystemCustomData.Custom1, 3, new ParticleSystem.MinMaxCurve(w));
            cd.SetMode(ParticleSystemCustomData.Custom2, ParticleSystemCustomDataMode.Color);
            cd.SetColor(ParticleSystemCustomData.Custom2, new ParticleSystem.MinMaxGradient(highlight));
        }

        static void Tsa(ParticleSystem ps, int x, int y, float f0, float f1)
        {
            var ts = ps.textureSheetAnimation; ts.enabled = true;
            ts.mode = ParticleSystemAnimationMode.Grid; ts.numTilesX = x; ts.numTilesY = y; ts.animation = ParticleSystemAnimationType.WholeSheet;
            ts.frameOverTime = new ParticleSystem.MinMaxCurve(f0, f1); ts.cycleCount = 1;
        }

        // Ramp up / hold / ramp down over the emission window (rise / fall = fraction of the window)
        static void Rate(ParticleSystem ps, float perSecond, float rise, float fall)
        {
            var em = ps.emission;
            em.SetBursts(new ParticleSystem.Burst[0]);
            float a = rise / Emit, b = 1f - fall / Emit;
            em.rateOverTime = new ParticleSystem.MinMaxCurve(perSecond, AnimCurve(0f, 0.15f, a, 1f, b, 1f, 1f, 0f));
        }

        // Read the mesh BEFORE choosing Start Rotation / alignment (art lead 2026-11-06: every mesh VFX must do this).
        // Logs the bounds and the likely axis of revolution of a ring / band / tube / funnel: the axis about which the vertex distance stays
        // most constant (lowest coefficient of variation), measured from the mesh origin. The Unity import axis is NOT always Y: the rpg-game
        // fbx files here have their axis on Z, so "upright" needs Start Rotation X = 90 (or 270) deg.
        static void Describe(Mesh m, string path)
        {
            var vs = m.vertices; string best = "?"; float bestCv = float.MaxValue;
            for (int a = 0; a < 3; a++)
            {
                float sum = 0, sum2 = 0;
                foreach (var v in vs) { float r = a == 0 ? Mathf.Sqrt(v.y * v.y + v.z * v.z) : a == 1 ? Mathf.Sqrt(v.x * v.x + v.z * v.z) : Mathf.Sqrt(v.x * v.x + v.y * v.y); sum += r; sum2 += r * r; }
                float mean = sum / vs.Length, cv = Mathf.Sqrt(Mathf.Max(0f, sum2 / vs.Length - mean * mean)) / Mathf.Max(1e-5f, mean);
                if (cv < bestCv) { bestCv = cv; best = "XYZ"[a].ToString(); }
            }
            Debug.Log("[VfxKit] mesh " + path + " bounds " + m.bounds.size.ToString("0.00") + " centre " + m.bounds.center.ToString("0.00") + " -> revolution axis ~ " + best + " (cv " + bestCv.ToString("0.00") + ")");
        }

        static Texture2D Tex(string path)
        {
            var t = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
            if (t == null) throw new System.InvalidOperationException("Texture missing: " + path);
            return t;
        }

        static Mesh LoadMesh(string path)
        {
            var m = AssetDatabase.LoadAssetAtPath<Mesh>(path);
            if (m == null) throw new System.InvalidOperationException("Mesh missing: " + path);
            Describe(m, path);
            return m;
        }
    }
}
#endif
